function save(){localStorage.setItem('cf-v18',JSON.stringify(state))} function levelFor(s){return [...LEVELS].reverse().find(x=>s>=x[0])[1]} function nextFor(s){return LEVELS.find(x=>x[0]>s)||null} function euro(n){return Number(n).toLocaleString('de-DE',{minimumFractionDigits:0,maximumFractionDigits:2})+' €'} function calc(){state.released=state.revenues.filter(x=>x.status==='eligible'&&!x.insurance).reduce((a,x)=>a+x.amount,0);state.pending=state.revenues.filter(x=>x.status==='pending'&&!x.insurance).reduce((a,x)=>a+x.amount,0)}
