function levelBar(){let l=levelFor(state.score),n=nextFor(state.score);return `<div class="level"><div class="level-head"><b>CF-Level ${l} %</b><span>${n?`Noch ${n[0]-state.score} Punkte bis ${n[1]} %`:'Maximales Level erreicht'}</span></div><div class="steps">${LEVELS.map(([p,x],i)=>`<div class="step ${x<=l?'on':''}"><i>${x<=l?'✓':''}</i><small>${x}%</small></div>${i<5?`<div class="line ${LEVELS[i+1][1]<=l?'on':''}"></div>`:''}`).join('')}</div></div>`}
